'use strict';

// MODULES //

var createHash = require( 'crypto' ).createHash;
var format = require( '@stdlib/string/format' );


// VARIABLES //

// Define a cap for the collision ordinal at six base-36 characters (zzzzzz), thus providing ~2.1 billion fallback IDs while retaining at least 55 digest characters within nbformat's 64-character cell-ID limit: (`c-`(2) + digest(55) + `-`(1) + ordinal(6) = 64)
var MAX_ORDINAL = 2176782336; // 36^6


// FUNCTIONS //

/**
* Returns a hexadecimal SHA-256 digest.
*
* @private
* @param {string} value - value
* @returns {string} digest
*/
function hash( value ) {
	return createHash( 'sha256' ).update( value ).digest( 'hex' );
}


// MAIN //

/**
* Returns a deterministic unique cell identifier.
*
* @private
* @param {string} type - cell type
* @param {Array} nodeIDs - contributing semantic node IDs
* @param {Object} state - ID state
* @throws {Error} attempted to emit the same semantic contribution twice
* @throws {Error} unable to allocate a unique cell ID
* @returns {string} cell ID
*/
function cellID( type, nodeIDs, state ) {
	var material;
	var ordinal;
	var digest;
	var length;
	var id;

	material = JSON.stringify( [ type, nodeIDs ] );
	digest = ( state.hash || hash )( material );
	for ( length = 20; length <= 60; length += 4 ) {
		id = format( 'c-%s', digest.slice( 0, length ) );
		if ( !state.occupied[ id ] ) {
			state.occupied[ id ] = material;
			return id;
		}
		if ( state.occupied[ id ] === material ) {
			throw new Error( 'internal error. Attempted to emit the same semantic contribution twice.' );
		}
	}
	ordinal = 1;
	while ( ordinal < MAX_ORDINAL ) {
		length = ordinal.toString( 36 ).length;
		id = format( 'c-%s-%s', digest.slice( 0, 61-length ), ordinal.toString( 36 ) );
		if ( !state.occupied[ id ] ) {
			state.occupied[ id ] = material;
			return id;
		}
		ordinal += 1;
	}
	throw new Error( 'internal error. Unable to allocate a unique notebook cell ID.' );
}


// EXPORTS //

module.exports = cellID;
